function App() {
  const [seed, setSeed] = useState('user-123');
  function bucket(id) {
    let h = 0;
    for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
    return h % 2 === 0 ? 'A' : 'B';
  }
  const variant = bucket(seed);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Edge A/B bucketing</h3>
      <input value={seed} onChange={e => setSeed(e.target.value)} style={{ padding: 6 }} />
      <p>Bucket: <b>variant {variant}</b></p>
      <p style={{ fontSize: 12, opacity: 0.7 }}>In middleware: NextResponse.rewrite(new URL(`/variant-${'{'}variant{'}'}`, request.url))</p>
    </div>
  );
}

